import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1787093302000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="does-this-work-with-calibre-web-automated" tabindex="-1">Does this work with Calibre-Web Automated? <a class="header-anchor" href="#does-this-work-with-calibre-web-automated" aria-label="Permalink to “Does this work with Calibre-Web Automated?”">​</a></h2><p>Yes. CWA keeps Calibre-Web&#39;s OPDS feed unchanged; everything here works the same way against it.</p><h2 id="why-do-some-books-have-id-null" tabindex="-1">Why do some books have <code>id: null</code>? <a class="header-anchor" href="#why-do-some-books-have-id-null" aria-label="Permalink to “Why do some books have id: null?”">​</a></h2><p>The OPDS entry itself carries only a UUID — the numeric Calibre id exists nowhere in it except inside the cover and download link hrefs. A book with no cover, requested by a user without the Download role, has neither link, so there is nothing to extract. The UUID is still returned; only <code>get_cover</code> is unavailable for that book (grant the Download role to fix it).</p><h2 id="http-401-on-every-call" tabindex="-1"><code>HTTP 401</code> on every call <a class="header-anchor" href="#http-401-on-every-call" aria-label="Permalink to “HTTP 401 on every call”">​</a></h2><p>Wrong <code>CALIBRE_WEB_USERNAME</code> / <code>CALIBRE_WEB_PASSWORD</code>. The OPDS feed uses the normal <strong>web login</strong> of the account — Calibre-Web has no separate API password. A 401 on a download URL specifically means the user lacks the <strong>Download</strong> role.</p><h2 id="http-403-on-view-read-unread" tabindex="-1"><code>HTTP 403</code> on <code>view: &quot;read&quot;</code> / <code>&quot;unread&quot;</code> <a class="header-anchor" href="#http-403-on-view-read-unread" aria-label="Permalink to “HTTP 403 on view: &quot;read&quot; / &quot;unread&quot;”">​</a></h2><p>Those feeds require a non-anonymous user with <strong>Show Read and Unread</strong> enabled in the user&#39;s view settings.</p><h2 id="http-404-on-a-view-that-should-exist" tabindex="-1"><code>HTTP 404</code> on a view that should exist <a class="header-anchor" href="#http-404-on-a-view-that-should-exist" aria-label="Permalink to “HTTP 404 on a view that should exist”">​</a></h2><p>Calibre-Web hides feeds according to the user&#39;s sidebar visibility settings (<strong>Admin → Edit User → View</strong>). A 404 on <code>hot</code>, <code>rated</code> or <code>discover</code> usually means that section is switched off for the configured user — or <code>CALIBRE_WEB_URL</code> does not point at the instance root.</p><h2 id="returned-an-html-page-instead-of-an-atom-feed" tabindex="-1">&quot;returned an HTML page instead of an Atom feed&quot; <a class="header-anchor" href="#returned-an-html-page-instead-of-an-atom-feed" aria-label="Permalink to “&quot;returned an HTML page instead of an Atom feed&quot;”">​</a></h2><p>The URL points somewhere that answers with HTML — typically the instance root is wrong, or a reverse proxy in front of Calibre-Web served its own login page. The server refuses to parse HTML rather than producing a confusing XML error.</p><h2 id="why-can-t-i-change-the-page-size" tabindex="-1">Why can&#39;t I change the page size? <a class="header-anchor" href="#why-can-t-i-change-the-page-size" aria-label="Permalink to “Why can&#39;t I change the page size?”">​</a></h2><p>It is a server-side setting (<strong>Admin → UI Configuration → Books per page</strong>, default 60). The OPDS feed paginates by it and offers no per-request override. Follow <code>pagination.nextOffset</code> instead of assuming a size.</p><h2 id="a-broad-search-fails-with-larger-than-8388608-bytes" tabindex="-1">A broad search fails with &quot;larger than 8388608 bytes&quot; <a class="header-anchor" href="#a-broad-search-fails-with-larger-than-8388608-bytes" aria-label="Permalink to “A broad search fails with &quot;larger than 8388608 bytes&quot;”">​</a></h2><p>Calibre-Web returns <strong>every</strong> search match in a single response; on a huge library a one-letter query can exceed the 8 MB feed cap. Narrow the query — the cap is what keeps a hostile or misconfigured instance from exhausting memory.</p><h2 id="why-is-the-cover-so-big-refused-over-1-mb" tabindex="-1">Why is the cover so big / refused over 1 MB? <a class="header-anchor" href="#why-is-the-cover-so-big-refused-over-1-mb" aria-label="Permalink to “Why is the cover so big / refused over 1 MB?”">​</a></h2><p>Calibre-Web serves the <strong>full-size</strong> cover on the OPDS cover route (the thumbnail aliases exist for client compatibility but serve the same file). <code>get_cover</code> refuses anything over 1 MB to protect the context window — for a larger scan, open the book&#39;s <code>coverUrl</code> in a browser instead.</p><h2 id="can-it-add-books-edit-metadata-or-manage-shelves" tabindex="-1">Can it add books, edit metadata, or manage shelves? <a class="header-anchor" href="#can-it-add-books-edit-metadata-or-manage-shelves" aria-label="Permalink to “Can it add books, edit metadata, or manage shelves?”">​</a></h2><p>No, and it will not. The OPDS feed is read-only; writing would mean driving Calibre-Web&#39;s session-based HTML forms, which is a different (and much more fragile) project. Every tool is a GET.</p><h2 id="where-are-the-author-series-tag-browsing-tools" tabindex="-1">Where are the author / series / tag browsing tools? <a class="header-anchor" href="#where-are-the-author-series-tag-browsing-tools" aria-label="Permalink to “Where are the author / series / tag browsing tools?”">​</a></h2><p><code>search_books</code> matches against title, authors, series, publisher and tags, which covers those lookups in practice. The index feeds exist in Calibre-Web, so dedicated tools are easy to add — <a href="https://github.com/ni-c/calibreweb-mcp/issues" target="_blank" rel="noreferrer">open an issue</a> with the use case.</p>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};